#!/usr/bin/env bash
# Generated by cloudcc. Builds a deployment artefact for each execution unit.
#
# Pulumi does not install dependencies for you, so this runs before
# `pulumi up`. `cloudcc deploy` invokes it automatically.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$here"

build="build"
rm -rf "$build"
mkdir -p "$build"

echo "packaging execution unit api"
unit_build="$build/api"
mkdir -p "$unit_build"

# The bundler resolves imports against node_modules, so the unit's
# dependencies have to be on disk first.
#
# npm install, never npm ci: cloudcc adds the runtime's own dependencies to
# package.json, so any lockfile copied from the source tree no longer matches
# it and npm ci would refuse. The stale lockfile is removed for the same
# reason -- keeping it would only mislead.
if [ -f "api/package.json" ]; then
  rm -f "api/package-lock.json"
  ( cd "api" && npm install --silent --omit=dev --no-audit --no-fund )
fi

# esbuild resolves and inlines the unit's dependencies, which sidesteps
# shipping node_modules in a zip -- the part of Node Lambda packaging that
# usually hurts. Native modules cannot be bundled; list them under
# `externals` in cloudcc.yaml if you have any.
bundler="npx --yes esbuild"
if command -v esbuild >/dev/null 2>&1; then
  bundler="esbuild"
fi

# The banner is not decoration. Bundling to ESM turns every CommonJS dependency
# into a module whose `require` esbuild replaces with a shim, and that shim
# throws for anything it did not bundle -- including Node's own builtins, which
# are external by definition. serverless-http reaches `require("http")` at load,
# so without this the bundle raises `Dynamic require of "node:https" is not
# supported` before the handler is ever called. Restoring a real `require` from
# import.meta.url is the standard remedy and costs one line in the output.
$bundler "api/cloudcc_lambda_entry.mjs" \
  --bundle \
  --platform=node \
  --target=node22 \
  --format=esm \
  --banner:js="import { createRequire as __cloudccCreateRequire } from 'node:module'; const require = __cloudccCreateRequire(import.meta.url);" \
  --outfile="$unit_build/index.mjs" \
  --log-level=warning

# Deterministic zip: fixed timestamps and sorted entries, so an unchanged unit
# produces a byte-identical artefact and Pulumi sees no diff.
find "$unit_build" -exec touch -t 198001010000 {} +
( cd "$unit_build" && find . -type f | LC_ALL=C sort | zip -q -X -@ "../api.zip" )
echo "  wrote $build/api.zip"

echo "packaging execution unit auditor"
unit_build="$build/auditor"
mkdir -p "$unit_build"

# The bundler resolves imports against node_modules, so the unit's
# dependencies have to be on disk first.
#
# npm install, never npm ci: cloudcc adds the runtime's own dependencies to
# package.json, so any lockfile copied from the source tree no longer matches
# it and npm ci would refuse. The stale lockfile is removed for the same
# reason -- keeping it would only mislead.
if [ -f "auditor/package.json" ]; then
  rm -f "auditor/package-lock.json"
  ( cd "auditor" && npm install --silent --omit=dev --no-audit --no-fund )
fi

# esbuild resolves and inlines the unit's dependencies, which sidesteps
# shipping node_modules in a zip -- the part of Node Lambda packaging that
# usually hurts. Native modules cannot be bundled; list them under
# `externals` in cloudcc.yaml if you have any.
bundler="npx --yes esbuild"
if command -v esbuild >/dev/null 2>&1; then
  bundler="esbuild"
fi

# The banner is not decoration. Bundling to ESM turns every CommonJS dependency
# into a module whose `require` esbuild replaces with a shim, and that shim
# throws for anything it did not bundle -- including Node's own builtins, which
# are external by definition. serverless-http reaches `require("http")` at load,
# so without this the bundle raises `Dynamic require of "node:https" is not
# supported` before the handler is ever called. Restoring a real `require` from
# import.meta.url is the standard remedy and costs one line in the output.
$bundler "auditor/cloudcc_lambda_entry.mjs" \
  --bundle \
  --platform=node \
  --target=node22 \
  --format=esm \
  --banner:js="import { createRequire as __cloudccCreateRequire } from 'node:module'; const require = __cloudccCreateRequire(import.meta.url);" \
  --outfile="$unit_build/index.mjs" \
  --log-level=warning

# Deterministic zip: fixed timestamps and sorted entries, so an unchanged unit
# produces a byte-identical artefact and Pulumi sees no diff.
find "$unit_build" -exec touch -t 198001010000 {} +
( cd "$unit_build" && find . -type f | LC_ALL=C sort | zip -q -X -@ "../auditor.zip" )
echo "  wrote $build/auditor.zip"

echo "packaging execution unit reporter (container)"

# Bundled first, exactly as the function path bundles: one artefact, produced
# one way, for both compute types. The image then carries a single index.mjs
# instead of a source tree plus node_modules, which is what makes a TypeScript
# unit runnable at all -- `node app.ts` is not a thing, and an image that copies
# sources and hopes is an image that starts and immediately exits.
#
# The dependencies still have to be on disk for the bundler to resolve them.
if [ -f "reporter/package.json" ]; then
  rm -f "reporter/package-lock.json"
  ( cd "reporter" && npm install --silent --omit=dev --no-audit --no-fund )
fi

bundler="npx --yes esbuild"
if command -v esbuild >/dev/null 2>&1; then
  bundler="esbuild"
fi

# The banner restores a real `require` for the CommonJS dependencies esbuild
# converts; see fragment-bundle.sh.tmpl for what it costs to leave out.
$bundler "reporter/cloudcc_server_entry.mjs" \
  --bundle \
  --platform=node \
  --target=node22 \
  --format=esm \
  --banner:js="import { createRequire as __cloudccCreateRequire } from 'node:module'; const require = __cloudccCreateRequire(import.meta.url);" \
  --outfile="reporter/index.mjs" \
  --log-level=warning

if command -v docker >/dev/null 2>&1; then
  docker build --quiet --tag "cloudcc-reporter:latest" "reporter" >/dev/null
  echo "  built image cloudcc-reporter:latest"
  echo "  push it after \`pulumi up\` with bin/push-images.sh"
else
  echo "  docker is not installed; skipping the image build for reporter" >&2
  echo "  install it with: brew install --cask docker" >&2
fi

echo "packaging complete"
